package metallurgy;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import javax.swing.table.TableRowSorter;
import java.awt.*;
import java.awt.event.*;
import java.nio.file.*;
import java.util.*;
import java.util.List;

/** Главное окно, действия пользователя и отображение истории расчетов. */
public class MainWindow extends JFrame {
    private final Database db; private final long user;
    private final String[] names={"Садка M, т","Глубина ванны l, м","Интенсивность q, м³/(т·мин)","Число сопел","Марганец [Mn], %","Угол конуса β, градусы","Коэффициент объема смеси"};
    private final JTextField[] fields=new JTextField[7]; private final JTextArea result=new JTextArea();
    private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Дата UTC","Масса, т","Глубина, м","q","Сопла","D, м","H, м","V, м³","V/M"},0){public boolean isCellEditable(int r,int c){return false;}public Class<?> getColumnClass(int c){return c==1?String.class:(c==0?Long.class:Double.class);}};
    private final JTable table=new JTable(model);private final TableRowSorter<DefaultTableModel> sorter=new TableRowSorter<>(model);
    private final JTextField filter=new JTextField(16); private final JRadioButton searchAll=new JRadioButton("Все поля",true), searchMass=new JRadioButton("Масса"); private final JCheckBox onlyRange=new JCheckBox("Только V/M 0,7–0,9");
    private List<Database.Entry> entries=List.of();private final ChartPanel chart=new ChartPanel(); private final SketchPanel sketch=new SketchPanel();
    public MainWindow(Database db,long user,String login){super("Калькулятор металлурга — "+login);this.db=db;this.user=user;setSize(1150,720);setLocationRelativeTo(null);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){try{db.close();}catch(Exception ignored){}dispose();}});
        JMenuBar bar=new JMenuBar();JMenu file=new JMenu("Файл");item(file,"Импорт CSV",()->importCsv());item(file,"Экспорт CSV",()->export("csv"));item(file,"Экспорт XLSX",()->export("xlsx"));item(file,"Отчет PDF",()->export("pdf"));item(file,"График PDF",()->export("chart"));bar.add(file);setJMenuBar(bar);
        JTabbedPane tabs=new JTabbedPane();tabs.addTab("Расчет",calculateTab());tabs.addTab("Проверки процесса",new ChecksPanel(this::input));tabs.addTab("История",historyTab());tabs.addTab("График",chart);tabs.addTab("Оборудование",equipmentTab());tabs.addTab("Справка",helpTab());add(tabs);refresh();calculate(false);
    }
    private void item(JMenu menu,String label,Runnable action){JMenuItem i=new JMenuItem(label);i.addActionListener(e->action.run());menu.add(i);}
    private JPanel calculateTab(){JPanel panel=new JPanel(new BorderLayout(10,10));panel.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));JPanel form=new JPanel(new GridLayout(0,2,8,8));String[] defaults={"200","1.6","3.2","4","0.6","30","1.15"};for(int i=0;i<fields.length;i++){form.add(new JLabel(names[i]));fields[i]=new JTextField(defaults[i]);form.add(fields[i]);}JButton calc=new JButton("Рассчитать"),save=new JButton("Сохранить расчет");calc.addActionListener(e->calculate(false));save.addActionListener(e->calculate(true));form.add(calc);form.add(save);JPanel left=new JPanel(new BorderLayout());left.add(form,BorderLayout.NORTH);result.setEditable(false);result.setFont(new Font(Font.MONOSPACED,Font.PLAIN,14));left.add(new JScrollPane(result),BorderLayout.CENTER);panel.add(left,BorderLayout.CENTER);panel.add(sketch,BorderLayout.EAST);return panel;}
    private ConverterCalculator.Input input(){double[] v=new double[7];for(int i=0;i<7;i++)v[i]=Double.parseDouble(fields[i].getText().trim().replace(',','.'));if(v[3]!=Math.rint(v[3]))throw new IllegalArgumentException("Число сопел должно быть целым");return new ConverterCalculator.Input(v[0],v[1],v[2],(int)v[3],v[4],v[5],v[6]);}
    private void calculate(boolean save){try{var x=input();var r=ConverterCalculator.calculate(x);result.setText(String.format(Locale.US,"Объем ванны:                 %.3f м³\nДиаметр рабочего пространства: %.3f м\nДиаметр днища:               %.3f м\nСвободная высота:             %.3f м\nВысота конвертера:            %.3f м\nДиаметр горловины:            %.3f м\nВысота верхнего конуса:       %.3f м\nВысота цилиндра:              %.3f м\nРабочий объем:                %.3f м³\nУдельный объем:               %.3f м³/т\nОтношение H/D:                %.3f\nМаксимальная глубина:         %.3f м\n\nСхема и расчет — учебная модель.\nОценочные ориентиры H/D: 1,4–1,8;\nV/M: 0,7–0,9 м³/т для обычного чугуна.\nПри отклонении проверьте исходные данные.",r.bathVolume(),r.diameter(),r.bottomDiameter(),r.freeHeight(),r.height(),r.mouthDiameter(),r.coneHeight(),r.cylinderHeight(),r.volume(),r.specificVolume(),r.heightRatio(),r.maxDepth()));sketch.setResult(r);if(save){db.insert(user,x);refresh();JOptionPane.showMessageDialog(this,"Расчет сохранен");}}catch(Exception e){error(e);}}
    private JPanel historyTab(){JPanel p=new JPanel(new BorderLayout());JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));top.add(new JLabel("Поиск:"));top.add(filter);ButtonGroup group=new ButtonGroup();group.add(searchAll);group.add(searchMass);top.add(searchAll);top.add(searchMass); JComboBox<String> sorting=new JComboBox<>(new String[]{"Порядок: дата", "Порядок: масса"}); sorting.addActionListener(e->{int column=sorting.getSelectedIndex()==0?1:2;sorter.setSortKeys(java.util.List.of(new RowSorter.SortKey(column,SortOrder.ASCENDING)));}); top.add(sorting);JButton find=new JButton("Применить"),clear=new JButton("Сбросить"),delete=new JButton("Удалить выделенное"),load=new JButton("В форму"),gen=new JButton("Сгенерировать");JSpinner count=new JSpinner(new SpinnerNumberModel(100,1,1000,1));top.add(find);top.add(clear);top.add(onlyRange);top.add(count);top.add(gen);top.add(load);top.add(delete);p.add(top,BorderLayout.NORTH);table.setRowSorter(sorter);p.add(new JScrollPane(table),BorderLayout.CENTER);find.addActionListener(e->applyFilter());onlyRange.addActionListener(e->applyFilter());clear.addActionListener(e->{filter.setText("");onlyRange.setSelected(false);applyFilter();});delete.addActionListener(e->deleteSelected());load.addActionListener(e->loadSelected());gen.addActionListener(e->generate((Integer)count.getValue()));return p;}
    private void applyFilter(){String s=filter.getText().trim().toLowerCase(Locale.ROOT);sorter.setRowFilter(new RowFilter<>(){public boolean include(Entry<? extends DefaultTableModel,? extends Integer> e){if(onlyRange.isSelected()){double v=((Number)e.getValue(9)).doubleValue();if(v<.7||v>.9)return false;}if(s.isEmpty())return true;if(searchMass.isSelected())return e.getStringValue(2).toLowerCase(Locale.ROOT).contains(s);for(int i=0;i<e.getValueCount();i++)if(e.getStringValue(i).toLowerCase(Locale.ROOT).contains(s))return true;return false;}});}
    private void refresh(){try{entries=db.list(user);model.setRowCount(0);for(var e:entries){var x=e.input();var r=ConverterCalculator.calculate(x);model.addRow(new Object[]{e.id(),e.time(),x.mass(),x.depth(),x.intensity(),(double)x.nozzles(),r.diameter(),r.height(),r.volume(),r.specificVolume()});}chart.setData(entries);applyFilter();}catch(Exception e){error(e);}}
    private void deleteSelected(){int n=table.getSelectedRow();if(n<0){error(new Exception("Выберите строку"));return;}long id=((Number)model.getValueAt(table.convertRowIndexToModel(n),0)).longValue();if(JOptionPane.showConfirmDialog(this,"Удалить выбранный расчет?","Удаление",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{db.delete(user,id);refresh();}catch(Exception e){error(e);}}
    private void loadSelected(){int n=table.getSelectedRow();if(n<0){error(new Exception("Выберите строку"));return;}long id=((Number)model.getValueAt(table.convertRowIndexToModel(n),0)).longValue();entries.stream().filter(e->e.id()==id).findFirst().ifPresent(e->{var x=e.input();String[] a={""+x.mass(),""+x.depth(),""+x.intensity(),""+x.nozzles(),""+x.manganese(),""+x.angle(),""+x.slagFactor()};for(int i=0;i<7;i++)fields[i].setText(a[i]);calculate(false);});JOptionPane.showMessageDialog(this,"Данные перенесены на вкладку «Расчет»");}
    private void generate(int count){try{Random random=new Random();for(int i=0;i<count;i++){double m=80+random.nextDouble()*220,depth=1.3+random.nextDouble()*.4,q=2.7+random.nextDouble()*.5;var x=new ConverterCalculator.Input(m,depth,q,4,.6,30,1.15);ConverterCalculator.calculate(x);db.insert(user,x);}refresh();JOptionPane.showMessageDialog(this,"Создано записей: "+count);}catch(Exception e){refresh();error(e);}}
    private Path choose(boolean save,String suffix){JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new java.io.File("metallurg."+suffix));int status=save?chooser.showSaveDialog(this):chooser.showOpenDialog(this);if(status!=JFileChooser.APPROVE_OPTION)return null;Path p=chooser.getSelectedFile().toPath();if(save&&!p.toString().toLowerCase().endsWith("."+suffix))p=Path.of(p+"."+suffix);if(save&&Files.exists(p)&&JOptionPane.showConfirmDialog(this,"Файл уже существует. Заменить?","Сохранение",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return null;return p;}
    private void importCsv(){Path p=choose(false,"csv");if(p==null)return;try{var list=ExportService.readCsv(p);for(var x:list)db.insert(user,x);refresh();JOptionPane.showMessageDialog(this,"Импортировано записей: "+list.size());}catch(Exception e){refresh();error(e);}}
    private void export(String type){String suffix=type.equals("chart")?"pdf":type;Path p=choose(true,suffix);if(p==null)return;try{switch(type){case "csv"->ExportService.csv(p,entries);case "xlsx"->ExportService.xlsx(p,entries);case "pdf"->ExportService.pdf(p,entries,false);case "chart"->ExportService.pdf(p,entries,true);}JOptionPane.showMessageDialog(this,"Сохранено: "+p);}catch(Exception e){error(e);}}
    private JPanel equipmentTab(){JPanel p=new JPanel(new BorderLayout());JTextArea text=new JTextArea("КИСЛОРОДНЫЙ КОНВЕРТЕР\n\nОборудование для получения стали продувкой жидкого металла кислородом.\nРасчет рассматривает внутреннее пространство агрегата: днище, цилиндрическую часть и горловину.\nРазмеры схемы определяются текущими значениями на вкладке «Расчет».\n\nСхема носит иллюстративный характер и не является рабочим чертежом.");text.setEditable(false);text.setLineWrap(true);text.setWrapStyleWord(true);p.add(text,BorderLayout.NORTH);return p;}
    private JScrollPane helpTab(){JTextArea t=new JTextArea("МЕТОДИКА: Токовой О. К. Производство стали и сплавов, 2013, раздел 2, с. 16–23.\n\nМодель: перевернутый усеченный конус. Принята плотность металла 7000 кг/м³. Глубина задается пользователем и проверяется на предел 2 м при нагрузке 1,4 кг/см². Для защиты днища и перемешивания необходимо отдельно рассчитать глубину проникновения струи и проверить минимальную глубину.\n\nVв = 1000 · M · f / 7000; D1 = 0,855 · D;\nD = √(12 · Vв / [π · l · (1 + 0,855 + 0,855²)]).\nHсв = k · (M · q / n)^0,4; H = l + Hсв.\nk = 1,17 – 0,58 · Mn при Mn ≤ 0,55%; иначе k = 0,73 + 0,22 · Mn.\nD2 = max(0,22√M; 0,12√(q·M)); hк = (D – D2)/(2·tg β).\nhц = Hсв – hк; Vц = πD²hц/4; Vк = πhк(D² + D·D2 + D2²)/12;\nV = Vв + Vц + Vк; v = V/M.\n\nКоэффициент f принят как приближенный по пособию; плотность шлака отдельно не учитывается. На вкладке «Проверки процесса» глубина струи и минимальная высота цилиндра оцениваются по дополнительно введенным данным. Материальный и тепловой балансы не вычисляются. Ориентиры — H/D 1,4–1,8 и v 0,7–0,9 м³/т для обычного чугуна.\n\nДля обмена выберите меню «Файл». CSV: UTF-8, разделитель ;, первые семь столбцов — исходные данные; экспорт содержит также результаты. Для сортировки щелкните заголовок таблицы. График показывает все сохраненные записи. Экспорт также включает все сохраненные записи независимо от фильтра.");t.setEditable(false);t.setLineWrap(true);t.setWrapStyleWord(true);t.setMargin(new Insets(16,16,16,16));return new JScrollPane(t);}
    private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Ошибка",JOptionPane.ERROR_MESSAGE);}
}
